package com.ruoyi.ai.agent;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import junit.framework.TestCase;
import java.util.UUID;
import static com.ruoyi.ai.agent.AgentJson.*;

/** The B9 core consumes authoritative persisted artifacts; no feature route is opened. */
public class B9ArtifactLineageMysqlTest extends TestCase {
    private A1TestFixture f;private AgentStore store;private AgentTools tools;private ObjectNode run,snapshot;
    protected void setUp() throws Exception {
        f=new A1TestFixture();store=new AgentStore(f.db);tools=new AgentTools(store);
        snapshot=(ObjectNode)parse("{\"id\":\"p\",\"sheetOrder\":[\"s\",\"out\"],\"sheets\":{\"s\":{\"id\":\"s\",\"name\":\"Source\",\"rowCount\":6,\"columnCount\":6,\"cellData\":{\"0\":{\"0\":{\"v\":\"Name\"},\"1\":{\"v\":\"Amount\"}},\"1\":{\"0\":{\"v\":\"A\"},\"1\":{\"v\":7}},\"2\":{\"0\":{\"v\":\"B\"},\"1\":{\"v\":9}}}},\"out\":{\"id\":\"out\",\"name\":\"Result\",\"rowCount\":6,\"columnCount\":6,\"cellData\":{}}}}");
        long w=f.seed(snapshot.toString()),b=f.request(w,-1,null,snapshot.toString()).getBranchId();run=obj().put("runId",UUID.randomUUID().toString()).put("userId",1L).put("workbookId",w).put("branchId",b).put("revision",hash(snapshot)).put("activeSheetId","out").put("allowOverwrite",false);run.set("writeScopes",arr().add(obj().put("sheetId","out").put("range","A1:B3")));
        f.db.update("insert into ai_agent_run(run_id,user_id,workbook_id,branch_id,request_id,request_hash,status,state_json,row_version,updated_at,created_at) values(?,?,?,?,?,?,'PAUSED',?,0,now(3),now(3))",run.path("runId").asText(),1,w,b,UUID.randomUUID().toString(),hash(run),run.toString());
    }
    private ObjectNode dataset(){ObjectNode a=obj().put("sheetId","s").put("range","A1:B3").put("headerRow",true).put("includeHidden",true).put("includeFiltered",true).put("formulaPolicy","reject");return tools.execute(run,"build_dataset",a,snapshot);}
    private ObjectNode args(JsonNode ref){ObjectNode a=obj().put("sheetId","out").put("range","A1:B3").put("overwrite","empty-only");a.set("dataset",ref);return a;}
    private void reject(Runnable r){try{r.run();fail("unsafe result write accepted");}catch(IllegalArgumentException e){assertNotNull(e.getMessage());}}
    public void testBuildAggregateAndBoundedExpansionPreserveSource(){ObjectNode input=dataset(),a=obj();a.set("dataset",input);a.set("groupBy",arr().add("Name"));a.set("sums",arr().add("Amount"));ObjectNode ref=tools.execute(run,"aggregate_table",a,snapshot),record=store.artifactRecord(run,text(ref,"resultRef"));assertEquals(1,record.path("lineage").size());assertEquals("s",record.path("lineage").get(0).path("sheetId").asText());ObjectNode manifest=tools.prepareResultWrite(run,args(ref),snapshot);assertEquals("setValues",manifest.path("actions").get(0).path("type").asText());assertEquals(text(ref,"resultRef"),manifest.path("resultSource").path("resultRef").asText());JsonNode saved=WriteManifest.apply(snapshot,manifest);assertEquals(snapshot.path("sheets").path("s"),saved.path("sheets").path("s"));assertEquals("Name",saved.path("sheets").path("out").path("cellData").path("0").path("0").path("v").asText());assertEquals(9,saved.path("sheets").path("out").path("cellData").path("2").path("1").path("v").asInt());}
    public void testDeriveAndJoinRetainCompleteLineage(){ObjectNode ref=dataset(),a=obj().put("nullPolicy","reject");a.set("dataset",ref);a.set("columns",arr().add(parse("{\"name\":\"Double\",\"op\":\"multiply\",\"left\":{\"field\":\"Amount\"},\"right\":{\"value\":2}}")));ObjectNode derived=tools.execute(run,"derive_columns",a,snapshot);assertEquals(store.artifactRecord(run,text(ref,"resultRef")).path("lineage"),store.artifactRecord(run,text(derived,"resultRef")).path("lineage"));ObjectNode join=obj().put("leftKey","Name").put("rightKey","Name").put("rightPrefix","r_").put("cardinality","many-to-one");join.set("left",ref);join.set("right",ref);ObjectNode joined=tools.execute(run,"join_tables",join,snapshot);assertEquals(1,store.artifactRecord(run,text(joined,"resultRef")).path("lineage").size());}
    public void testSourceSheetTargetVersionAndReferenceForgeryReject(){ObjectNode ref=dataset(),a=args(ref);a.put("sheetId","s");reject(()->tools.prepareResultWrite(run,a,snapshot));ObjectNode forged=ref.deepCopy();forged.put("sourceRevision","forged");reject(()->tools.prepareResultWrite(run,args(forged),snapshot));ObjectNode changed=snapshot.deepCopy();((ObjectNode)changed.path("sheets").path("s").path("cellData").path("1").path("1")).put("v",8);reject(()->tools.prepareResultWrite(run,args(ref),changed));ObjectNode other=run.deepCopy();other.put("runId",UUID.randomUUID().toString());reject(()->tools.prepareResultWrite(other,args(ref),snapshot));}
    public void testLegacyReadableButUntrackedWriteAndPermissionChangeReject(){String id=store.artifact(run,parse("{\"columns\":[\"x\"],\"rows\":[{\"x\":1}]}"));assertEquals(1,store.artifact(run,id).path("rows").size());ObjectNode ref=obj().put("resultRef",id).put("sourceRevision",run.path("revision").asText());reject(()->tools.prepareResultWrite(run,args(ref),snapshot));ObjectNode tracked=dataset();f.db.update("update ai_workbook_branch set status='archived' where branch_id=?",run.path("branchId").asLong());reject(()->tools.prepareResultWrite(run,args(tracked),snapshot));}
    public void testStoredEnvelopeTamperAndShapeReject(){ObjectNode ref=dataset(),record=store.artifactRecord(run,text(ref,"resultRef")),a=args(ref);a.put("range","A1:B2");reject(()->tools.prepareResultWrite(run,a,snapshot));ObjectNode forgedArgs=args(ref);forgedArgs.set("values",arr().add(arr().add("forged")));reject(()->tools.prepareResultWrite(run,forgedArgs,snapshot));f.db.update("update ai_analysis_artifact set content_json=json_set(content_json,'$.data.rows[0].Amount',999) where artifact_id=?",text(ref,"resultRef"));reject(()->tools.prepareResultWrite(run,args(ref),snapshot));}
    public void testMalformedAndDangerousMatricesReject(){ObjectNode ref=dataset();JsonNode lineage=store.artifactRecord(run,text(ref,"resultRef")).path("lineage");for(String json:new String[]{"{\"columns\":[\"x\",\"x\"],\"rows\":[{\"x\":1}]}","{\"columns\":[\"x\",\"y\"],\"rows\":[{\"x\":1}]}","{\"columns\":[\"x\"],\"rows\":[{\"x\":\" =SUM(A1:A2)\"}]}","{\"columns\":[\"x\"],\"rows\":[{\"x\":{}}]}","{\"columns\":[\"x\"],\"rows\":[]}"}){String id=store.artifact(run,parse(json),lineage);ObjectNode bad=obj().put("resultRef",id).put("sourceRevision",run.path("revision").asText());reject(()->tools.prepareResultWrite(run,args(bad),snapshot));}}
    public void testPartialLegacyJoinDoesNotGainTrustedLineage(){ObjectNode tracked=dataset();String id=store.artifact(run,parse("{\"columns\":[\"Name\",\"Amount\"],\"rows\":[{\"Name\":\"A\",\"Amount\":7}]}"));ObjectNode old=obj().put("resultRef",id).put("sourceRevision",run.path("revision").asText()),join=obj().put("leftKey","Name").put("rightKey","Name").put("rightPrefix","r_").put("cardinality","many-to-one");join.set("left",tracked);join.set("right",old);ObjectNode result=tools.execute(run,"join_tables",join,snapshot);assertEquals(0,store.artifactRecord(run,text(result,"resultRef")).path("lineage").size());reject(()->tools.prepareResultWrite(run,args(result),snapshot));}
    public void testScalarValuesAndExplicitColumnOrder(){ObjectNode tracked=dataset();JsonNode lineage=store.artifactRecord(run,text(tracked,"resultRef")).path("lineage");JsonNode data=parse("{\"columns\":[\"second\",\"first\"],\"rows\":[{\"first\":false,\"second\":null},{\"first\":\"\",\"second\":0}]}");String id=store.artifact(run,data,lineage);ObjectNode ref=obj().put("resultRef",id).put("sourceRevision",run.path("revision").asText()),m=tools.prepareResultWrite(run,args(ref),snapshot);assertEquals(parse("[[\"second\",\"first\"],[null,false],[0,\"\"]]"),m.path("actions").get(0).path("values"));}
    public void testWriteBudgetRejectsBeforeTargetExpansion(){ObjectNode tracked=dataset();JsonNode lineage=store.artifactRecord(run,text(tracked,"resultRef")).path("lineage");ArrayNode rows=arr();for(int i=0;i<500;i++)rows.add(obj().put("Name","x").put("Amount",i));ObjectNode data=obj();data.set("columns",arr().add("Name").add("Amount"));data.set("rows",rows);String id=store.artifact(run,data,lineage);ObjectNode ref=obj().put("resultRef",id).put("sourceRevision",run.path("revision").asText());reject(()->tools.prepareResultWrite(run,args(ref),snapshot));assertEquals(6,snapshot.path("sheets").path("out").path("rowCount").asInt());}
}
